from decimal import Decimal
from ledgerly.adjustments import goodwill_credit
from ledgerly.models import Invoice, LineItem
from ledgerly.errors import BillingError
from ledgerly import audit

def inv(status="issued", price="50.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(price))],status=status)

# basic
print(goodwill_credit(inv(), Decimal("5.00"), "late"))
# non-positive
for a in [Decimal("0"), Decimal("-1")]:
    try: goodwill_credit(inv(), a, "x")
    except BillingError as e: print("nonpos", e.code)
# exceeds total
try: goodwill_credit(inv(), Decimal("50.01"), "x")
except BillingError as e: print("exceeds", e.code)
# not issued
try: goodwill_credit(inv("draft"), Decimal("5"), "x")
except BillingError as e: print("state", e.code)
# float
try: goodwill_credit(inv(), 5.0, "x")
except BillingError as e: print("float", e.code)
# approval
try: goodwill_credit(inv(price="2000.00"), Decimal("1500.00"), "x")
except BillingError as e: print("approval", e.code)
print(goodwill_credit(inv(price="2000.00"), Decimal("1500.00"), "x", approved_by="mgr"))
# idempotency
r1 = goodwill_credit(inv(), Decimal("5.00"), "late", idempotency_key="k1")
r2 = goodwill_credit(inv(), Decimal("5.00"), "late", idempotency_key="k1")
print("idem", r1 == r2, len(audit.events("goodwill_credit")))
EOF"}

